/**
 * Dynamische ALT en TITLE voor featured images.
 * Gebruikt automatisch de titel van de huidige post.
 */
add_filter( 'wp_get_attachment_image_attributes', function( $attr, $attachment, $size ) {

    if ( ! is_singular() ) {
        return $attr;
    }

    $post_id = get_queried_object_id();

    if ( ! $post_id ) {
        return $attr;
    }

    $featured_image_id = get_post_thumbnail_id( $post_id );

    // Alleen aanpassen als deze afbeelding de featured image
    // van de huidige post is.
    if ( (int) $attachment->ID !== (int) $featured_image_id ) {
        return $attr;
    }

    $post_title = get_the_title( $post_id );

    if ( ! $post_title ) {
        return $attr;
    }

    // ALT-tekst
    $attr['alt'] = $post_title;

    // HTML title attribute
    $attr['title'] = $post_title;

    return $attr;

}, 10, 3 );

add_filter( 'elementor/utils/get_the_archive_title', function( $title ) {

    if ( is_category() ) {
        return single_cat_title( '', false );
    }

    if ( is_tag() ) {
        return single_tag_title( '', false );
    }

    if ( is_tax() ) {
        return single_term_title( '', false );
    }

    if ( is_post_type_archive() ) {
        return post_type_archive_title( '', false );
    }

    return $title;
});

/**
 * Deze snippet is voor de archives van beroepen, om de query die informatie bevat te tonen (beroepen posts of current taxonomies), zodat we 1 archive template kunnen gebruiken voor allen. 
 * 
 * TFSC - Archive context classes
 *
 * Voor één generiek archive-template met:
 *
 * .tfsc_query_beroepen
 * .tfsc_query_taxonomies_current
 * 
 */

add_filter( 'body_class', function( $classes ) {

    // CPT archive Beroepen.
    if ( is_post_type_archive( 'beroep' ) ) {
        $classes[] = 'tfsc-archive-beroepen';
    }

    // TFSC taxonomy-base archive.
    if ( get_query_var( 'tfsc_taxonomy_archive' ) ) {
        $classes[] = 'tfsc-archive-taxonomy';
    }

    return $classes;
});

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * Query ID's:
 *
 * taxonomy_level_X
 *
 * current_taxonomy
 * current_taxonomy_level_X
 */


/**
 * Term IDs van exact taxonomy-level ophalen.
 */
function tfsc_taxonomy_level_term_ids(
    $taxonomy,
    $level
) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return [];
    }

    $terms = get_terms( [
        'taxonomy'   => $taxonomy,
        'hide_empty' => false,
    ] );

    if (
        is_wp_error( $terms ) ||
        ! $terms
    ) {
        return [];
    }

    $ids = [];

    foreach ( $terms as $term ) {

        if (
            count(
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
            ) === (int) $level
        ) {
            $ids[] = (int) $term->term_id;
        }
    }

    return $ids;
}


/**
 * Elementor Taxonomy Loop.
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
            ?? ''
        );

        if ( ! $query_id ) {
            return $args;
        }


        /**
         * ====================================================
         * taxonomy_level_X
         * ====================================================
         */

        if (
            preg_match(
                '/^taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $taxonomy =
                $args['taxonomy']
                ?? '';

            if ( is_array( $taxonomy ) ) {
                $taxonomy = reset( $taxonomy );
            }

            if ( ! taxonomy_exists( $taxonomy ) ) {
                return $args;
            }

            unset(
                $args['term_taxonomy_id']
            );

            $ids =
                tfsc_taxonomy_level_term_ids(
                    $taxonomy,
                    (int) $matches[1]
                );

            $args['include'] =
                $ids ?: [ 0 ];

            return $args;
        }


        /**
         * ====================================================
         * current_taxonomy
         * current_taxonomy_level_X
         * ====================================================
         */

        $is_current =
            'current_taxonomy' === $query_id;

        $has_level =
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            );

        if (
            ! $is_current &&
            ! $has_level
        ) {
            return $args;
        }


        $taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $taxonomy &&
            isset( $GLOBALS['wp_query'] )
        ) {
            $taxonomy =
                $GLOBALS['wp_query']->get(
                    'tfsc_taxonomy_archive'
                );
        }

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']   = $taxonomy;
        $args['hide_empty'] = false;
        $args['orderby']    = 'name';
        $args['order']      = 'ASC';


        /**
         * current_taxonomy = alle terms.
         */
        if ( $is_current ) {
            return $args;
        }


        /**
         * current_taxonomy_level_X.
         */
        $ids =
            tfsc_taxonomy_level_term_ids(
                $taxonomy,
                (int) $matches[1]
            );

        $args['include'] =
            $ids ?: [ 0 ];

        return $args;
    },
    20,
    3
);

/**
 * TFSC - Rank Math breadcrumbs voor combo-archieven
 *
 * Voorbeeld:
 * Home > Vacatures > Field Service Engineer > Elektrotechniek
 */

add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        if (
            ! function_exists( 'tfsc_is_combo_archive' ) ||
            ! function_exists( 'tfsc_get_combo_archive' ) ||
            ! tfsc_is_combo_archive()
        ) {
            return $crumbs;
        }

        $combo = tfsc_get_combo_archive();

        if ( ! is_array( $combo ) || ! $combo ) {
            return $crumbs;
        }

        $base = trim( TFSC_COMBO_BASE, '/' );

        $new_crumbs = [
            [
                'Home',
                home_url( '/' ),
            ],
            [
                'Vacatures',
                home_url( '/' . $base . '/' ),
            ],
        ];

        $path_parts = [];
        $last_index = count( $combo ) - 1;

        foreach ( $combo as $index => $item ) {

            if (
                empty( $item['taxonomy'] ) ||
                empty( $item['term'] ) ||
                ! $item['term'] instanceof WP_Term
            ) {
                continue;
            }

            $term = $item['term'];

            $path_parts[] =
                sanitize_key(
                    $item['taxonomy']
                );

            if (
                ! empty( $item['path'] ) &&
                is_array( $item['path'] )
            ) {

                foreach ( $item['path'] as $path_term ) {

                    if ( $path_term instanceof WP_Term ) {
                        $path_parts[] = $path_term->slug;
                    }
                }

            } else {

                $path_parts[] = $term->slug;
            }

            $url =
                home_url(
                    '/'
                    . $base
                    . '/'
                    . implode(
                        '/',
                        array_map(
                            'rawurlencode',
                            $path_parts
                        )
                    )
                    . '/'
                );

            $new_crumbs[] = [
                $term->name,
                $index === $last_index
                    ? ''
                    : $url,
            ];
        }

        return $new_crumbs;
    },
    20,
    2
);

/**
 * TFSC - Alle taxonomy termen in WordPress linkzoeker
 *
 * Alle publieke native taxonomy-term archieven.
 * Geen virtuele combo-URL's.
 */

add_filter(
    'wp_link_query',
    function( $results, $query ) {

        $search = trim(
            (string) ( $query['s'] ?? '' )
        );

        if ( '' === $search ) {
            return $results;
        }

        $taxonomies = array_keys(
            get_taxonomies(
                [
                    'public'             => true,
                    'publicly_queryable' => true,
                ],
                'objects'
            )
        );

        $taxonomies = array_values(
            array_diff(
                $taxonomies,
                [ 'post_format' ]
            )
        );

        if ( ! $taxonomies ) {
            return $results;
        }

        $terms = get_terms( [
            'taxonomy'   => $taxonomies,
            'hide_empty' => false,
            'search'     => $search,
            'number'     => 50,
        ] );

        if (
            is_wp_error( $terms ) ||
            ! $terms
        ) {
            return $results;
        }

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $GLOBALS['tfsc_force_native_term_link'] = true;
            $url = get_term_link( $term );
            unset( $GLOBALS['tfsc_force_native_term_link'] );

            if ( is_wp_error( $url ) ) {
                continue;
            }

            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );

            $results[] = [
                'ID' =>
                    'term-'
                    . $term->taxonomy
                    . '-'
                    . $term->term_id,

                'title' =>
                    $term->name,

                'permalink' =>
                    $url,

                'info' =>
                    $taxonomy->labels->singular_name
                    ?? $term->taxonomy,
            ];
        }

        return $results;
    },
    20,
    2
);

/**
 * TFSC - Dynamische Archive Description Accordion
 *
 * Shortcode:
 * [tfsc_archive_accordion]
 *
 * Titel:
 * pods_archive_title → termnaam
 *
 * Content:
 * term description
 */


/**
 * Eén accordion-item maken.
 */
function tfsc_get_archive_accordion_item( $term ) {

    if ( ! $term instanceof WP_Term ) {
        return false;
    }

    $description = trim(
        (string) term_description(
            $term->term_id,
            $term->taxonomy
        )
    );

    if ( '' === $description ) {
        return false;
    }

    $title = get_term_meta(
        $term->term_id,
        'pods_archive_title',
        true
    );

    $title = is_string( $title )
        ? trim( wp_strip_all_tags( $title ) )
        : '';

    if ( '' === $title ) {
        $title = trim( $term->name );
    }

    if ( '' === $title ) {
        return false;
    }

    return [
        'title'       => $title,
        'description' => $description,
        'term_id'     => (int) $term->term_id,
        'taxonomy'    => $term->taxonomy,
    ];
}


/**
 * Actieve archive-terms bepalen.
 */
function tfsc_get_archive_accordion_terms() {

    /**
     * Virtueel combo archive.
     */
    if (
        function_exists( 'tfsc_is_combo_archive' ) &&
        function_exists( 'tfsc_get_combo_archive' ) &&
        tfsc_is_combo_archive()
    ) {

        $combo = tfsc_get_combo_archive();

        if ( ! is_array( $combo ) ) {
            return [];
        }

        $terms = [];
        $seen  = [];

        foreach ( $combo as $item ) {

            $term = $item['term'] ?? null;

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $key =
                $term->taxonomy
                . ':'
                . $term->term_id;

            if ( isset( $seen[ $key ] ) ) {
                continue;
            }

            $seen[ $key ] = true;
            $terms[] = $term;
        }

        return $terms;
    }

    /**
     * Native taxonomy archive.
     */
    if ( ! is_tax() ) {
        return [];
    }

    $term = get_queried_object();

    if ( ! $term instanceof WP_Term ) {
        return [];
    }

    $status_taxonomy =
        defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';

    if ( $term->taxonomy === $status_taxonomy ) {
        return [];
    }

    /**
     * Hoofd-combosnippet gebruiken indien beschikbaar.
     */
    if (
        function_exists( 'tfsc_combo_taxonomy_allowed' )
    ) {
        return tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
            ? [ $term ]
            : [];
    }

    /**
     * Fallback: taxonomy moet aan vacature hangen.
     */
    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    $post_type =
        defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';

    if (
        ! $taxonomy ||
        ! in_array(
            $post_type,
            (array) $taxonomy->object_type,
            true
        )
    ) {
        return [];
    }

    return [ $term ];
}


/**
 * Accordion-items ophalen.
 */
function tfsc_get_archive_accordion_items() {

    $items = [];

    foreach (
        tfsc_get_archive_accordion_terms()
        as $term
    ) {

        $item =
            tfsc_get_archive_accordion_item(
                $term
            );

        if ( $item ) {
            $items[] = $item;
        }
    }

    return $items;
}


/**
 * Shortcode.
 */
add_shortcode(
    'tfsc_archive_accordion',
    function() {

        $items =
            tfsc_get_archive_accordion_items();

        if ( ! $items ) {
            return '';
        }

        static $instance = 0;
        $instance++;

        $accordion_id =
            'tfsc-archive-accordion-'
            . $instance;

        ob_start();
        ?>

        <div
            id="<?php echo esc_attr( $accordion_id ); ?>"
            class="tfsc-archive-accordion"
        >

            <?php foreach ( $items as $index => $item ) :

                $item_id =
                    $accordion_id
                    . '-item-'
                    . $index;

                $button_id =
                    $item_id . '-button';

                $content_id =
                    $item_id . '-content';
            ?>

                <div
                    class="tfsc-archive-accordion__item"
                    data-taxonomy="<?php echo esc_attr( $item['taxonomy'] ); ?>"
                    data-term-id="<?php echo esc_attr( $item['term_id'] ); ?>"
                >

                    <button
                        type="button"
                        id="<?php echo esc_attr( $button_id ); ?>"
                        class="tfsc-archive-accordion__title"
                        aria-expanded="false"
                        aria-controls="<?php echo esc_attr( $content_id ); ?>"
                    >
                        <span class="tfsc-archive-accordion__title-text">
                            <?php echo esc_html( $item['title'] ); ?>
                        </span>

                        <span
                            class="tfsc-archive-accordion__chevron"
                            aria-hidden="true"
                        ></span>
                    </button>

                    <div
                        id="<?php echo esc_attr( $content_id ); ?>"
                        class="tfsc-archive-accordion__content"
                        role="region"
                        aria-labelledby="<?php echo esc_attr( $button_id ); ?>"
                        hidden
                    >
                        <div class="tfsc-archive-accordion__content-inner">
                            <?php
                            echo wp_kses_post(
                                $item['description']
                            );
                            ?>
                        </div>
                    </div>

                </div>

            <?php endforeach; ?>

        </div>

        <script>
        (function () {

            const accordion =
                document.getElementById(
                    <?php echo wp_json_encode( $accordion_id ); ?>
                );

            if (!accordion) {
                return;
            }

            accordion.addEventListener(
                'click',
                function (event) {

                    const button =
                        event.target.closest(
                            '.tfsc-archive-accordion__title'
                        );

                    if (
                        !button ||
                        !accordion.contains(button)
                    ) {
                        return;
                    }

                    const item =
                        button.closest(
                            '.tfsc-archive-accordion__item'
                        );

                    const content =
                        item?.querySelector(
                            '.tfsc-archive-accordion__content'
                        );

                    if (!content) {
                        return;
                    }

                    const open =
                        button.getAttribute(
                            'aria-expanded'
                        ) === 'true';

                    button.setAttribute(
                        'aria-expanded',
                        String(!open)
                    );

                    item.classList.toggle(
                        'tfsc-archive-accordion__item--open',
                        !open
                    );

                    content.hidden = open;
                }
            );

        })();
        </script>

        <?php
        return ob_get_clean();
    }
);


