/**
 * TFSC - Generic Current Taxonomy Term Fields
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Generieke laag voor custom fields op ALLE taxonomy terms.
 *
 * Werkt met:
 *
 * - normale taxonomy term archives
 * - Elementor Taxonomy Loop Grid / Loop Carousel
 * - Pods custom fields op taxonomy terms
 * - iedere taxonomy
 *
 * De taxonomy hoeft nergens handmatig geselecteerd te worden.
 *
 *
 * ============================================================
 * CONTEXT
 * ============================================================
 *
 * Op een normale term archive:
 *
 * get_queried_object()
 *
 * Op een Elementor Taxonomy Loop:
 *
 * $wp_query->loop_term
 *
 * Elementor zet tijdens iedere kaart de huidige term daarin.
 *
 * Voorbeeld:
 *
 * kaart 1 → Field Service Engineer
 * kaart 2 → Commissioning Engineer
 * kaart 3 → Service Engineer
 *
 * Hierdoor kan dezelfde Dynamic Tag per kaart automatisch
 * het Pods field van de juiste term uitlezen.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Tekst:
 *
 * [tfsc_term_field field="intro_taxonomy"]
 *
 * Image URL:
 *
 * [tfsc_term_field field="archive_featured_image" output="url"]
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * TFSC Current Term Field
 * → voor tekst/custom fields
 *
 * TFSC Current Term Image
 * → voor image widgets/background images
 *
 *
 * Voorbeeld afbeelding:
 *
 * Background
 * → Dynamic
 * → TFSC Current Term Image
 * → archive_featured_image
 *
 *
 * Voorbeeld tekst:
 *
 * Heading/Text
 * → Dynamic
 * → TFSC Current Term Field
 * → intro_taxonomy
 */


/**
 * ============================================================
 * 1. CURRENT TERM CONTEXT
 * ============================================================
 */
function tfsc_current_term() {

    global $wp_query;

    /**
     * Elementor Taxonomy Loop.
     *
     * Elementor zet tijdens iedere loop-iteratie de huidige
     * taxonomy term in $wp_query->loop_term.
     */
    if (
        $wp_query instanceof WP_Query
        && isset( $wp_query->loop_term )
        && $wp_query->loop_term instanceof WP_Term
    ) {
        return $wp_query->loop_term;
    }

    /**
     * Normale taxonomy term archive.
     */
    $object = get_queried_object();

    if ( $object instanceof WP_Term ) {
        return $object;
    }

    return null;
}


/**
 * ============================================================
 * 2. CURRENT TERM FIELD
 * ============================================================
 *
 * Leest een Pods field van de huidige taxonomy-term.
 *
 * Werkt dus automatisch met:
 *
 * beroep_functienaam
 * beroep_kennisgebied
 * beroep_opleiding
 * enz.
 *
 * Fallback naar normale WordPress term-meta.
 */
function tfsc_current_term_field( $field ) {

    $term = tfsc_current_term();

    if ( ! $term || ! $field ) {
        return null;
    }

    $field = sanitize_key( $field );

    if ( function_exists( 'pods' ) ) {

        $pod = pods(
            $term->taxonomy,
            $term->term_id
        );

        if ( $pod && $pod->exists() ) {
            return $pod->field( $field );
        }
    }

    return get_term_meta(
        $term->term_id,
        $field,
        true
    );
}


/**
 * ============================================================
 * 3. IMAGE ATTACHMENT ID
 * ============================================================
 *
 * Zet mogelijke Pods File/Image returnwaarden om naar
 * één WordPress attachment ID.
 */
function tfsc_current_term_image_id( $field ) {

    $value = tfsc_current_term_field( $field );

    if ( empty( $value ) ) {
        return 0;
    }

    if ( is_numeric( $value ) ) {
        return (int) $value;
    }

    if ( is_array( $value ) ) {

        if (
            isset( $value['ID'] )
            || isset( $value['id'] )
            || isset( $value['pod_item_id'] )
        ) {
            return (int) (
                $value['ID']
                ?? $value['id']
                ?? $value['pod_item_id']
            );
        }

        /**
         * Pods kan een file/image field ook als lijst
         * van attachment records retourneren.
         */
        $first = reset( $value );

        if ( is_array( $first ) ) {
            return (int) (
                $first['ID']
                ?? $first['id']
                ?? $first['pod_item_id']
                ?? 0
            );
        }

        if ( is_object( $first ) ) {
            return (int) (
                $first->ID
                ?? $first->id
                ?? $first->pod_item_id
                ?? 0
            );
        }
    }

    if ( is_object( $value ) ) {

        return (int) (
            $value->ID
            ?? $value->id
            ?? $value->pod_item_id
            ?? 0
        );
    }

    return 0;
}


/**
 * ============================================================
 * 4. GENERIEKE SHORTCODE
 * ============================================================
 *
 * Tekst:
 *
 * [tfsc_term_field field="intro_taxonomy"]
 *
 * Afbeelding URL:
 *
 * [tfsc_term_field
 *     field="archive_featured_image"
 *     output="url"
 * ]
 */
add_shortcode(
    'tfsc_term_field',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'  => '',
                'output' => 'text',
                'size'   => 'full',
            ],
            $atts,
            'tfsc_term_field'
        );

        $field = sanitize_key( $atts['field'] );

        if ( ! $field ) {
            return '';
        }

        if ( $atts['output'] === 'url' ) {

            $id = tfsc_current_term_image_id( $field );

            if ( ! $id ) {
                return '';
            }

            $url = wp_get_attachment_image_url(
                $id,
                sanitize_key( $atts['size'] )
            );

            return $url
                ? esc_url( $url )
                : '';
        }

        $value = tfsc_current_term_field( $field );

        if (
            is_array( $value )
            || is_object( $value )
        ) {
            return '';
        }

        return wp_kses_post(
            (string) $value
        );
    }
);


/**
 * ============================================================
 * 5. ELEMENTOR DYNAMIC TAGS
 * ============================================================
 */
add_action(
    'elementor/dynamic_tags/register',
    function( $dynamic_tags ) {

        if (
            ! class_exists(
                '\Elementor\Core\DynamicTags\Data_Tag'
            )
        ) {
            return;
        }


        /**
         * ----------------------------------------------------
         * TFSC CURRENT TERM FIELD
         * ----------------------------------------------------
         *
         * Voor tekstvelden.
         */
        if (
            ! class_exists(
                'TFSC_Current_Term_Field_Tag'
            )
        ) {

            class TFSC_Current_Term_Field_Tag
                extends \Elementor\Core\DynamicTags\Tag {

                public function get_name() {
                    return 'tfsc-current-term-field';
                }

                public function get_title() {
                    return 'TFSC Current Term Field';
                }

                public function get_group() {
                    return 'site';
                }

                public function get_categories() {

                    return [
                        \Elementor\Modules\DynamicTags\Module::TEXT_CATEGORY,
                    ];
                }

                protected function register_controls() {

                    $this->add_control(
                        'field',
                        [
                            'label'       => 'Term field',
                            'type'        =>
                                \Elementor\Controls_Manager::TEXT,
                            'placeholder' =>
                                'intro_taxonomy',
                        ]
                    );
                }

                public function render() {

                    $field = sanitize_key(
                        $this->get_settings( 'field' )
                    );

                    if ( ! $field ) {
                        return;
                    }

                    $value =
                        tfsc_current_term_field(
                            $field
                        );

                    if (
                        is_array( $value )
                        || is_object( $value )
                    ) {
                        return;
                    }

                    echo wp_kses_post(
                        (string) $value
                    );
                }
            }

            $dynamic_tags->register(
                new TFSC_Current_Term_Field_Tag()
            );
        }


        /**
         * ----------------------------------------------------
         * TFSC CURRENT TERM IMAGE
         * ----------------------------------------------------
         *
         * Voor:
         *
         * - Image widget
         * - Container background
         * - andere Elementor image controls
         */
        if (
            ! class_exists(
                'TFSC_Current_Term_Image_Tag'
            )
        ) {

            class TFSC_Current_Term_Image_Tag
                extends \Elementor\Core\DynamicTags\Data_Tag {

                public function get_name() {
                    return 'tfsc-current-term-image';
                }

                public function get_title() {
                    return 'TFSC Current Term Image';
                }

                public function get_group() {
                    return 'site';
                }

                public function get_categories() {

                    return [
                        \Elementor\Modules\DynamicTags\Module::IMAGE_CATEGORY,
                    ];
                }

                protected function register_controls() {

                    $this->add_control(
                        'field',
                        [
                            'label'       => 'Term field',
                            'type'        =>
                                \Elementor\Controls_Manager::TEXT,
                            'default'     =>
                                'archive_featured_image',
                            'placeholder' =>
                                'archive_featured_image',
                        ]
                    );
                }

                public function get_value(
                    array $options = []
                ) {

                    $field = sanitize_key(
                        $this->get_settings( 'field' )
                    );

                    if ( ! $field ) {
                        return [];
                    }

                    $id =
                        tfsc_current_term_image_id(
                            $field
                        );

                    if ( ! $id ) {
                        return [];
                    }

                    $url =
                        wp_get_attachment_image_url(
                            $id,
                            'full'
                        );

                    if ( ! $url ) {
                        return [];
                    }

                    return [
                        'id'  => $id,
                        'url' => $url,
                    ];
                }
            }

            $dynamic_tags->register(
                new TFSC_Current_Term_Image_Tag()
            );
        }
    }
);

/**
 * TFSC - Vacature Button URL + Text
 *
 * Shortcodes:
 *
 * [vacature_button_url]
 * [vacature_button_text]
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * 1. relationship_vacature_button_url gevuld?
 *
 *    → gebruik native taxonomy-term URL
 *    → buttontekst = naam van die term
 *
 * 2. relationship_vacature_button_url leeg?
 *
 *    CPT / post:
 *    → tfsc_derived_rel_v3_relationship_groups()
 *
 *    Taxonomy / term:
 *    → tfsc_taxrel_v4_relationship_groups()
 *
 *    → bouw één TFSC combo archive URL
 *    → buttontekst = "Bekijk vacatures"
 */


/**
 * ============================================================
 * 1. HUIDIGE POD
 * ============================================================
 */

function tfsc_vacature_button_v4_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /**
     * Taxonomy-term.
     *
     * Gebruik indien mogelijk dezelfde resolver als
     * de taxonomy relationship-loop.
     */
    if (
        function_exists( 'tfsc_taxrel_v4_current_term' )
    ) {
        $term = tfsc_taxrel_v4_current_term();

        if ( $term instanceof WP_Term ) {

            $pod = pods(
                $term->taxonomy,
                (int) $term->term_id
            );

            return (
                $pod &&
                $pod->exists()
            )
                ? $pod
                : false;
        }
    }

    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * CPT / post / Elementor preview.
     */
    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v2_get_context_post_id();

    } elseif (
        $object instanceof WP_Post
    ) {
        $post_id = (int) $object->ID;

    } else {
        $post_id =
            (int) get_queried_object_id();
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if (
        ! $post_type ||
        'elementor_library' === $post_type
    ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 2. EXPLICIETE BUTTON TERM
 * ============================================================
 *
 * relationship_vacature_button_url
 */

function tfsc_vacature_button_v4_explicit_term() {

    $pod =
        tfsc_vacature_button_v4_pod();

    if ( ! $pod ) {
        return false;
    }

    $value =
        $pod->field(
            'relationship_vacature_button_url'
        );

    if ( empty( $value ) ) {
        return false;
    }

    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    foreach ( (array) $value as $relation ) {

        $term_id  = 0;
        $taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );
        }

        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $term;
        }
    }

    return false;
}


/**
 * ============================================================
 * 3. ACTIEVE RELATIONSHIP GROUPS
 * ============================================================
 *
 * Taxonomy-term:
 * → tfsc_taxrel_v4_relationship_groups()
 *
 * CPT / post:
 * → tfsc_derived_rel_v3_relationship_groups()
 */

function tfsc_vacature_button_v4_relationship_groups() {

    $object =
        get_queried_object();

    /**
     * Taxonomy context.
     */
    if (
        $object instanceof WP_Term ||
        (
            function_exists(
                'tfsc_taxrel_v4_current_term'
            ) &&
            tfsc_taxrel_v4_current_term()
            instanceof WP_Term
        )
    ) {

        return function_exists(
            'tfsc_taxrel_v4_relationship_groups'
        )
            ? tfsc_taxrel_v4_relationship_groups()
            : [];
    }

    /**
     * CPT / post context.
     */
    return function_exists(
        'tfsc_derived_rel_v3_relationship_groups'
    )
        ? tfsc_derived_rel_v3_relationship_groups()
        : [];
}


/**
 * ============================================================
 * 4. TERM PATH
 * ============================================================
 */

function tfsc_vacature_button_v4_term_path(
    $term
) {

    if (
        function_exists(
            'tfsc_taxrel_v4_term_path'
        )
    ) {
        return tfsc_taxrel_v4_term_path(
            $term
        );
    }

    if (
        function_exists(
            'tfsc_derived_rel_v3_term_path'
        )
    ) {
        return tfsc_derived_rel_v3_term_path(
            $term
        );
    }

    if ( ! $term instanceof WP_Term ) {
        return '';
    }

    return rawurlencode(
        $term->slug
    );
}


/**
 * ============================================================
 * 5. COMBO BASE
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_base() {

    if ( defined( 'TFSC_COMBO_BASE' ) ) {
        return TFSC_COMBO_BASE;
    }

    return 'vacatures';
}


/**
 * ============================================================
 * 6. COMBO URL
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_url() {

    $groups =
        tfsc_vacature_button_v4_relationship_groups();

    if ( ! $groups ) {
        return '';
    }

    $parts = [
        tfsc_vacature_button_v4_combo_base(),
    ];

    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    (int) $term_id,
                    $taxonomy
                );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $path =
                tfsc_vacature_button_v4_term_path(
                    $term
                );

            if ( ! $path ) {
                continue;
            }

            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }

    if ( count( $parts ) <= 1 ) {
        return '';
    }

    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                static fn( $part ) =>
                    trim( $part, '/' ),
                $parts
            )
        )
        .
        '/'
    );
}


