/**
 * ============================================================
 * RANK MATH CUSTOM SITEMAP PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',

    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }


        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {

            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements
                \RankMath\Sitemap\Providers\Provider {


                public function handles_type(
                    $type
                ) {

                    return (
                        'combo-vacatures'
                        === $type
                    );
                }


                public function get_index_links(
                    $max_entries
                ) {

                    $links =
                        tfsc_combo_sitemap_generate_links();


                    $total =
                        count(
                            $links
                        );


                    if ( 0 === $total ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $pages =
                        max(
                            1,
                            (int) ceil(
                                $total
                                /
                                $max_entries
                            )
                        );


                    $index = [];


                    for (
                        $page = 1;
                        $page <= $pages;
                        $page++
                    ) {

                        $suffix =
                            $pages > 1
                                ? $page
                                : '';


                        $offset =
                            (
                                $page - 1
                            )
                            *
                            $max_entries;


                        $page_links =
                            array_slice(
                                $links,
                                $offset,
                                $max_entries
                            );


                        $page_lastmod = '';


                        foreach (
                            $page_links
                            as $page_link
                        ) {

                            if (
                                empty(
                                    $page_link[
                                        'lastmod'
                                    ]
                                )
                            ) {
                                continue;
                            }


                            $page_lastmod =
                                tfsc_combo_sitemap_newest_lastmod(
                                    $page_lastmod,
                                    $page_link[
                                        'lastmod'
                                    ]
                                );
                        }


                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    $suffix
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                $page_lastmod,
                        ];
                    }


                    return $index;
                }


                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if (
                        'combo-vacatures'
                        !== $type
                    ) {
                        return [];
                    }


                    $links =
                        tfsc_combo_sitemap_generate_links();


                    if ( ! $links ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $page =
                        max(
                            1,
                            (int) $current_page
                        );


                    $offset =
                        (
                            $page - 1
                        )
                        *
                        $max_entries;


                    return array_slice(
                        $links,
                        $offset,
                        $max_entries
                    );
                }
            }
        }


        $providers[
            'combo-vacatures'
        ] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();


        return $providers;
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 4.3 - Stable Legacy Logic + S&F Pagination Sync
 *
 * Gebaseerd op de oude werkende combo-architectuur.
 *
 * Regelt:
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen dezelfde taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 frontend sync
 * - Elementor archive condition
 * - Native vacature taxonomy archives
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 * - Correcte /page/N/ pagination rewrite
 * - Main query gebruikt dezelfde posts_per_page als S&F Query 1
 *
 * Belangrijk:
 * - Geen server-side Search & Filter query manipulation
 * - Geen search_filter_query_id koppeling
 * - Geen search-filter/query/query_args mutatie
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define( 'TFSC_COMBO_BASE', 'vacatures' );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define( 'TFSC_STATUS_TAXONOMY', 'vac_status' );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define( 'TFSC_OPEN_STATUS_SLUG', 'open' );
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if (
        ! $taxonomy ||
        TFSC_STATUS_TAXONOMY === $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $object = get_taxonomy( $taxonomy );

    return (
        $object &&
        $object->publicly_queryable &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    static $allowed = null;

    if ( null !== $allowed ) {
        return $allowed;
    }

    $allowed = [];

    foreach (
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        )
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/* ============================================================
 * SEARCH & FILTER POSTS PER PAGE
 * ============================================================
 *
 * Search & Filter Query 1 is de bron voor de paginagrootte.
 *
 * Als S&F bijvoorbeeld 10 resultaten per pagina gebruikt,
 * gebruikt de WordPress main query ook 10.
 *
 * Daardoor krijgen:
 *
 * - WordPress
 * - Rank Math
 * - combo pagination
 * - Search & Filter
 *
 * dezelfde page count.
 * ============================================================ */

function tfsc_get_search_filter_posts_per_page() {

    static $resolved = false;
    static $value    = null;

    if ( $resolved ) {
        return $value;
    }

    $resolved = true;


    if (
        ! class_exists(
            '\Search_Filter\Queries\Query'
        )
    ) {
        return null;
    }


    try {

        $sf_query =
            \Search_Filter\Queries\Query::find(
                [
                    'id' =>
                        (int) TFSC_SEARCH_FILTER_QUERY_ID,
                ]
            );

    } catch ( Throwable $e ) {

        return null;
    }


    if (
        is_wp_error( $sf_query ) ||
        ! is_object( $sf_query ) ||
        ! method_exists(
            $sf_query,
            'get_attribute'
        )
    ) {
        return null;
    }


    $posts_per_page =
        $sf_query->get_attribute(
            'postsPerPage'
        );


    if (
        null === $posts_per_page ||
        '' === $posts_per_page
    ) {
        return null;
    }


    $posts_per_page =
        (int) $posts_per_page;


    if ( -1 === $posts_per_page ) {
        return $value = -1;
    }


    if ( $posts_per_page < 1 ) {
        return null;
    }


    return $value =
        $posts_per_page;
}


