            class TFSC_Vacancy_Taxonomy_Term_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type() {
                    return 'archive';
                }


                public static function get_priority() {
                    return 41;
                }


