/**
 * TFSC - Base Taxonomies Related Posts
 *
 * Doel:
 * Toon op een virtuele taxonomy base archive alle posts
 * uit de in Elementor gekozen Source die minimaal één term
 * hebben binnen de actieve taxonomy.
 *
 * Voorbeeld:
 *
 * /beroepengids/functienamen/
 *
 * actieve taxonomy:
 * beroep_functienaam
 *
 * Elementor Source:
 * beroepengids
 *
 * resultaat:
 * alle beroepengids-posts die minimaal één
 * beroep_functienaam-term hebben.
 *
 * Elementor Query ID:
 *
 * base_taxonomies_related_posts
 */


/**
 * ============================================================
 * 1. ACTIEVE TAXONOMY BASE ARCHIVE
 * ============================================================
 */

function tfsc_base_taxonomies_related_posts_current_taxonomy() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return '';
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if (
        is_object( $taxonomy ) &&
        ! empty( $taxonomy->name )
    ) {
        $taxonomy =
            $taxonomy->name;
    }

    $taxonomy =
        sanitize_key(
            (string) $taxonomy
        );

    if (
        ! $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return '';
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 2. ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID:
 * base_taxonomies_related_posts
 *
 * LET OP:
 * De Elementor Source blijft leidend.
 *
 * Deze query verandert dus NIET het post type.
 * Hij voegt alleen de actieve taxonomy base toe
 * als EXISTS-filter.
 */

add_action(
    'elementor/query/base_taxonomies_related_posts',
    function( $query ) {

        $taxonomy =
            tfsc_base_taxonomies_related_posts_current_taxonomy();

        if ( ! $taxonomy ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }

        /**
         * Alleen posts tonen die minimaal één term
         * hebben binnen de actieve taxonomy.
         *
         * Het post type / de Source blijft volledig
         * door Elementor bepaald.
         */
        $query->set(
            'tax_query',
            [
                [
                    'taxonomy' =>
                        $taxonomy,

                    'operator' =>
                        'EXISTS',
                ],
            ]
        );
    },
    30
);

/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals + Filter SEO
 * Version 4.3 - Location Combo Support
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * ============================================================
 * REGELT
 * ============================================================
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Correcte canonical voor /page/N/
 * - Correcte OpenGraph URL voor /page/N/
 * - Correcte CollectionPage schema URL voor /page/N/
 * - Correcte rel prev / next
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * INDEXERINGSLOGICA
 * - functienaam-combo: index/follow
 * - locatie-only combo: index/follow
 * - overige combo zonder functienaam: noindex/follow
 * - meer dan 3 taxonomies: noindex/follow
 * - minimaal 1 resultaat vereist
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven bereikbaar
 * - index/follow
 * - functienaam → equivalente combo
 * - locatie → equivalente locatie-only combo
 * - overige taxonomies → legacy FSE-combo
 * - pagination blijft behouden
 *
 * SEARCH & FILTER URLS OP /vacatures/
 * - noindex, follow
 * - canonical naar schone /vacatures/
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {

    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {

    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY',
        'functienaam'
    );
}


if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


if (
    ! defined(
        'TFSC_COMBO_SEO_LOCATION_TAXONOMY'
    )
) {

    define(
        'TFSC_COMBO_SEO_LOCATION_TAXONOMY',
        'locatie'
    );
}


/* ============================================================
 * HUIDIGE PAGINA
 * ============================================================ */

function tfsc_combo_seo_get_paged() {

    return max(
        1,
        (int) get_query_var(
            'paged'
        )
    );
}


/* ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================ */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }


    if (
        ! function_exists(
            'tfsc_is_combo_archive'
        )
        ||
        ! function_exists(
            'tfsc_get_combo_archive'
        )
    ) {
        return false;
    }


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    return (
        false !==
        tfsc_get_combo_archive()
    );
}


/* ============================================================
 * COMBO VOLGORDE
 * ============================================================ */

function tfsc_combo_seo_order_combo(
    array $combo
) {

    $function = [];
    $others   = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! empty(
                $item['taxonomy']
            )
            &&
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
                ===
            $item['taxonomy']
        ) {

            $function[] =
                $item;

        } else {

            $others[] =
                $item;
        }
    }


    return array_merge(
        $function,
        $others
    );
}


/* ============================================================
 * COMBO ITEMS
 * ============================================================ */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];


    if ( $resolved ) {
        return $items;
    }


    $resolved =
        true;


    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return [];
    }


    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array(
            $combo
        )
    ) {
        return [];
    }


    $combo =
        tfsc_combo_seo_order_combo(
            $combo
        );


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! $item['term']
                instanceof WP_Term
        ) {
            continue;
        }


        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );


        if (
            '' === $name
        ) {
            continue;
        }


        $items[] = [
            'taxonomy' =>
                (string)
                $item['taxonomy'],

            'term_id' =>
                (int)
                $item['term']->term_id,

            'slug' =>
                (string)
                $item['term']->slug,

            'name' =>
                $name,
        ];
    }


    return $items;
}


/* ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================ */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if (
        null === $combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {
            return 0;
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
    ) {
        return 0;
    }


    $taxonomies =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
        ) {
            continue;
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
        ) {
            continue;
        }


        $taxonomies[
            $taxonomy
        ] = true;
    }


    return count(
        $taxonomies
    );
}


