/* ============================================================
 * CORRECTE COMBO PREV / NEXT
 * ============================================================ */

function tfsc_combo_output_prev_next() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return;
    }


    $prev =
        tfsc_combo_seo_get_prev_url();


    $next =
        tfsc_combo_seo_get_next_url();


    if (
        '' !== $prev
    ) {

        echo '<link rel="prev" href="'
            .
            esc_url(
                $prev
            )
            .
            '" />'
            .
            "\n";
    }


    if (
        '' !== $next
    ) {

        echo '<link rel="next" href="'
            .
            esc_url(
                $next
            )
            .
            '" />'
            .
            "\n";
    }
}


