/**
 * TFSC - Dynamische tekst shortcodes
 *
 * Shortcodes:
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * ============================================================
 * CASE
 * ============================================================
 *
 * case="normal"
 * case="lower"
 * case="sentence"
 *
 *
 * ============================================================
 * [archive_title] MODES
 * ============================================================
 *
 * Term archives:
 *
 * current
 * parents
 * full
 * label_current
 * label_full
 *
 * Taxonomy base archives:
 *
 * taxonomy
 * taxonomy_plural
 *
 *
 * ============================================================
 * PODS OUTPUT
 * ============================================================
 *
 * [tfsc_pods] gebruikt voor normale Pods velden:
 *
 *     $pod->display()
 *
 * in plaats van:
 *
 *     $pod->field()
 *
 * Hierdoor worden de OUTPUT SETTINGS van het Pods veld gebruikt.
 *
 * Dit is met name belangrijk voor:
 *
 * - WYSIWYG velden
 * - wpautop
 * - HTML sanitizing
 * - shortcodes
 * - wptexturize
 * - convert_chars
 *
 * Relationship velden worden apart verwerkt omdat display()
 * daar niet altijd de gewenste losse namen oplevert.
 *
 * BELANGRIJK:
 *
 * case="lower" en case="sentence" worden NIET toegepast op
 * HTML/WYSIWYG output. Daarmee zouden namelijk ook HTML tags
 * en attributen kunnen worden aangepast.
 */


/**
 * ============================================================
 * 1. CONTEXT POST ID
 * ============================================================
 */

function tfsc_text_context_post_id() {

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v3_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    $object =
        get_queried_object();


    if (
        $object instanceof WP_Post
    ) {

        return (int)
            $object->ID;
    }


    return (int)
        get_the_ID();
}


/**
 * ============================================================
 * 2. CONTEXT POD
 * ============================================================
 */

function tfsc_text_context_pod() {

    if (
        ! function_exists(
            'pods'
        )
    ) {
        return false;
    }


    $object =
        get_queried_object();


    /**
     * --------------------------------------------------------
     * TAXONOMY TERM
     * --------------------------------------------------------
     */

    if (
        $object instanceof WP_Term
    ) {

        $pod =
            pods(
                $object->taxonomy,
                (int) $object->term_id
            );


        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * --------------------------------------------------------
     * POST / CPT / ELEMENTOR PREVIEW
     * --------------------------------------------------------
     */

    $post_id =
        tfsc_text_context_post_id();


    if ( ! $post_id ) {
        return false;
    }


    $post_type =
        get_post_type(
            $post_id
        );


    if ( ! $post_type ) {
        return false;
    }


    $pod =
        pods(
            $post_type,
            $post_id
        );


    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 3. TAXONOMY BASE OBJECT
 * ============================================================
 */

function tfsc_text_taxonomy_archive_object() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return false;
    }


    $taxonomy =
        tfsc_get_current_taxonomy_archive();


    if (
        $taxonomy instanceof WP_Taxonomy
    ) {

        return $taxonomy;
    }


    if (
        is_string(
            $taxonomy
        )
    ) {

        $taxonomy =
            get_taxonomy(
                sanitize_key(
                    $taxonomy
                )
            );


        return (
            $taxonomy instanceof WP_Taxonomy
        )
            ? $taxonomy
            : false;
    }


    return false;
}


/**
 * ============================================================
 * 4. TEXT CASE
 * ============================================================
 */

function tfsc_text_case(
    $text,
    $case = 'normal'
) {

    $text =
        (string) $text;


    if (
        '' === $text
    ) {
        return '';
    }


    switch (
        sanitize_key(
            $case
        )
    ) {

        /**
         * ----------------------------------------------------
         * LOWERCASE
         * ----------------------------------------------------
         */

        case 'lower':

            return
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * SENTENCE CASE
         * ----------------------------------------------------
         */

        case 'sentence':

            $text =
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


            return

                mb_strtoupper(
                    mb_substr(
                        $text,
                        0,
                        1,
                        'UTF-8'
                    ),
                    'UTF-8'
                )

                .

                mb_substr(
                    $text,
                    1,
                    null,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * NORMAL
         * ----------------------------------------------------
         */

        default:

            return $text;
    }
}


/**
 * ============================================================
 * 5. [post_title]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [post_title]
 *
 * [post_title case="lower"]
 *
 * [post_title before="Vacature: "]
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'before' => '',
                    'after'  => '',
                    'case'   => 'normal',
                ],
                $atts,
                'post_title'
            );


        $post_id =
            tfsc_text_context_post_id();


        if ( ! $post_id ) {
            return '';
        }


        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );


        if (
            '' === $title
        ) {
            return '';
        }


        $title =
            tfsc_text_case(
                $title,
                $atts['case']
            );


        return
            (string) $atts['before']
            . $title
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * 6. [archive_title]
 * ============================================================
 *
 * TERM ARCHIVE MODES
 *
 * [archive_title]
 * [archive_title mode="current"]
 * [archive_title mode="parents"]
 * [archive_title mode="full"]
 * [archive_title mode="label_current"]
 * [archive_title mode="label_full"]
 *
 *
 * TAXONOMY BASE ARCHIVE MODES
 *
 * [archive_title mode="taxonomy"]
 * [archive_title mode="taxonomy_plural"]
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'mode'            => 'current',
                    'separator'       => ' › ',
                    'label_separator' => ': ',
                    'before'          => '',
                    'after'           => '',
                    'case'            => 'normal',
                ],
                $atts,
                'archive_title'
            );


        $mode =
            sanitize_key(
                $atts['mode']
            );


        $object =
            get_queried_object();


        /**
         * ====================================================
         * TAXONOMY TERM ARCHIVE
         * ====================================================
         */

        if (
            $object instanceof WP_Term &&
            taxonomy_exists(
                $object->taxonomy
            )
        ) {

            $taxonomy =
                $object->taxonomy;


            $current =
                wp_strip_all_tags(
                    $object->name
                );


            $parents = [];


            /**
             * Hiërarchische parents verzamelen.
             */

            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $object->term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $parents[] =
                            wp_strip_all_tags(
                                $ancestor->name
                            );
                    }
                }
            }


            /**
             * Taxonomy label.
             */

            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            $label =
                (
                    $taxonomy_object &&
                    ! empty(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                )
                    ? wp_strip_all_tags(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                    : '';


            /**
             * Volledige parentstructuur.
             */

            $full =
                implode(
                    (string)
                    $atts['separator'],
                    array_merge(
                        $parents,
                        [ $current ]
                    )
                );


            switch (
                $mode
            ) {

                /**
                 * Parents zonder current term.
                 */

                case 'parents':

                    $output =
                        implode(
                            (string)
                            $atts['separator'],
                            $parents
                        );

                    break;


                /**
                 * Parents + current term.
                 */

                case 'full':

                    $output =
                        $full;

                    break;


                /**
                 * Taxonomy label + current term.
                 */

                case 'label_current':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $current
                            : $current;

                    break;


                /**
                 * Taxonomy label + volledige hiërarchie.
                 */

                case 'label_full':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $full
                            : $full;

                    break;


                /**
                 * Alleen huidige term.
                 */

                default:

                    $output =
                        $current;
            }


        /**
         * ====================================================
         * TAXONOMY BASE ARCHIVE
         * ====================================================
         */

        } else {

            $taxonomy_object =
                tfsc_text_taxonomy_archive_object();


            if (
                ! $taxonomy_object
            ) {
                return '';
            }


            switch (
                $mode
            ) {

                /**
                 * Meervoud taxonomy label.
                 */

                case 'taxonomy_plural':

                    $output =
                        $taxonomy_object
                            ->labels
                            ->name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';

                    break;


                /**
                 * Enkelvoud taxonomy label.
                 */

                case 'taxonomy':
                default:

                    $output =
                        $taxonomy_object
                            ->labels
                            ->singular_name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';
            }


            $output =
                wp_strip_all_tags(
                    (string)
                    $output
                );
        }


        if (
            '' === $output
        ) {
            return '';
        }


        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );


        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);


/**
 * ============================================================
 * 7. [tfsc_pods]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [tfsc_pods field="intro"]
 *
 * [tfsc_pods field="functie"]
 *
 * [tfsc_pods field="sector" separator=", "]
 *
 * [tfsc_pods field="plaats" case="lower"]
 *
 *
 * ============================================================
 * BELANGRIJK VOOR WYSIWYG
 * ============================================================
 *
 * Voor scalar / tekstvelden wordt:
 *
 * $pod->display()
 *
 * gebruikt.
 *
 * Hierdoor gebruikt Pods zelf de ingestelde Output Options
 * van het veld.
 *
 * Dus bijvoorbeeld bij WYSIWYG:
 *
 * - wpautop
 * - sanitize HTML
 * - wptexturize
 * - convert_chars
 * - shortcodes
 *
 * hoeven hier NIET opnieuw door PHP uitgevoerd te worden.
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'field'     => '',
                    'before'    => '',
                    'after'     => '',
                    'separator' => ', ',
                    'case'      => 'normal',
                ],
                $atts,
                'tfsc_pods'
            );


        /**
         * ----------------------------------------------------
         * FIELD
         * ----------------------------------------------------
         */

        $field =
            sanitize_key(
                $atts['field']
            );


        if (
            ! $field
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * POD CONTEXT
         * ----------------------------------------------------
         */

        $pod =
            tfsc_text_context_pod();


        if (
            ! $pod
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * RAW VALUE
         * ----------------------------------------------------
         *
         * field() gebruiken we hier alleen om te bepalen
         * of het om een scalar of relationship/array gaat.
         */

        $value =
            $pod->field(
                $field
            );


        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }


        /**
         * ====================================================
         * SCALAR / TEKST / WYSIWYG
         * ====================================================
         */

        if (
            ! is_array(
                $value
            ) &&
            ! is_object(
                $value
            )
        ) {

            /**
             * Pods verzorgt zelf de frontend output.
             *
             * Voor WYSIWYG worden hierdoor de Output Options
             * van het veld gerespecteerd.
             */

            $output =
                $pod->display(
                    $field
                );


            if (
                null === $output ||
                false === $output
            ) {
                return '';
            }


            $output =
                (string)
                $output;


            if (
                '' === trim(
                    $output
                )
            ) {
                return '';
            }


            /**
             * ------------------------------------------------
             * CASE
             * ------------------------------------------------
             *
             * Alleen toepassen wanneer de output geen HTML
             * bevat.
             *
             * Dit voorkomt dat WYSIWYG HTML kapot wordt
             * gemaakt door strtolower/sentence case.
             */

            if (
                $output ===
                wp_strip_all_tags(
                    $output
                )
            ) {

                $output =
                    tfsc_text_case(
                        $output,
                        $atts['case']
                    );
            }


        /**
         * ====================================================
         * RELATIONSHIP / ARRAY / OBJECT
         * ====================================================
         */

        } else {

            /**
             * Eén relationship normaliseren naar array.
             */

            if (
                is_object(
                    $value
                )
                ||
                (
                    is_array(
                        $value
                    )
                    &&
                    (
                        isset(
                            $value['name']
                        )
                        ||
                        isset(
                            $value['post_title']
                        )
                        ||
                        isset(
                            $value['title']
                        )
                    )
                )
            ) {

                $value =
                    [ $value ];
            }


            $names = [];


            foreach (
                (array)
                $value
                as $relation
            ) {

                /**
                 * --------------------------------------------
                 * ARRAY RELATIONSHIP
                 * --------------------------------------------
                 */

                if (
                    is_array(
                        $relation
                    )
                ) {

                    $name =
                        $relation['name']
                        ??
                        $relation['post_title']
                        ??
                        $relation['title']
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * OBJECT RELATIONSHIP
                 * --------------------------------------------
                 */

                } elseif (
                    is_object(
                        $relation
                    )
                ) {

                    $name =
                        $relation->name
                        ??
                        $relation->post_title
                        ??
                        $relation->title
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * ONBEKEND
                 * --------------------------------------------
                 */

                } else {

                    $name = '';
                }


                $name =
                    wp_strip_all_tags(
                        (string)
                        $name
                    );


                if (
                    '' !== $name
                ) {

                    $names[] =
                        $name;
                }
            }


            /**
             * Dubbelen verwijderen en samenvoegen.
             */

            $names =
                array_values(
                    array_unique(
                        $names
                    )
                );


            $output =
                implode(
                    (string)
                    $atts['separator'],
                    $names
                );


            if (
                '' === $output
            ) {
                return '';
            }


            /**
             * Relationships zijn gewone tekst,
             * dus case kan hier veilig worden toegepast.
             */

            $output =
                tfsc_text_case(
                    $output,
                    $atts['case']
                );
        }


        /**
         * ====================================================
         * OUTPUT
         * ====================================================
         */

        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);

/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v3_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        $query->set(
            'tax_query',
            $relationship_query
        );
    },
    20,
    1
);

/**
 * TFSC - Post Terms Buttons
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont de taxonomy terms die aan de huidige post / CPT
 * gekoppeld zijn als klikbare buttons.
 *
 * Werkt ook in Elementor Theme Builder previews wanneer
 * tfsc_derived_rel_v3_get_context_post_id() beschikbaar is.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Alle publieke taxonomies met gekoppelde terms:
 *
 * [tfsc_post_terms]
 *
 * Eén taxonomy:
 *
 * [tfsc_post_terms taxonomy="kennisgebied"]
 *
 * Meerdere taxonomies:
 *
 * [tfsc_post_terms taxonomy="functienaam,kennisgebied,locatie"]
 *
 *
 * ============================================================
 * LINKS
 * ============================================================
 *
 * Iedere term linkt naar zijn normale native taxonomy URL.
 *
 * De TFSC combo-link omzetting wordt bewust tijdelijk
 * uitgeschakeld via:
 *
 * tfsc_force_native_term_link
 *
 *
 * ============================================================
 * OUTPUT
 * ============================================================
 *
 * .tfsc-post-terms
 * .tfsc-post-terms__item
 * .tfsc-post-terms__item--{taxonomy}
 */
/**
 * ============================================================
 * CSS
 * ============================================================
 *
 * Voeg onderstaande CSS toe in Elementor Custom CSS,
 * Site Settings of je eigen stylesheet:
 *
 *
 * .tfsc-post-terms {
 *     display: flex;
 *     flex-wrap: wrap;
 *     gap: 8px;
 * }
 *
 * .tfsc-post-terms__item {
 *     display: inline-flex;
 *     align-items: center;
 *     padding: 8px 14px;
 *     border: 1px solid currentColor;
 *     border-radius: 999px;
 *     text-decoration: none;
 * }
 *
 *
 * ============================================================
 * TAXONOMY-SPECIFIEKE STYLING
 * ============================================================
 *
 * Iedere button krijgt ook een class met de taxonomy name.
 *
 * Bijvoorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied
 * .tfsc-post-terms__item--functienaam
 * .tfsc-post-terms__item--locatie
 *
 * Daardoor kun je taxonomies afzonderlijk stylen.
 *
 * Voorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied {
 *     font-weight: 600;
 * }
 *
 *
 * ============================================================
 * HOVER
 * ============================================================
 *
 * Eventueel:
 *
 * .tfsc-post-terms__item:hover {
 *     text-decoration: none;
 * }
 */

add_shortcode(
    'tfsc_post_terms',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'taxonomy' => '',
            ],
            $atts,
            'tfsc_post_terms'
        );


        /**
         * ====================================================
         * HUIDIGE POST / ELEMENTOR PREVIEW
         * ====================================================
         */

        $post_id = 0;

        if (
            function_exists(
                'tfsc_derived_rel_v3_get_context_post_id'
            )
        ) {
            $post_id =
                (int)
                tfsc_derived_rel_v3_get_context_post_id();

        } elseif (
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
        ) {
            $post_id =
                (int)
                tfsc_derived_rel_v2_get_context_post_id();
        }

        if ( ! $post_id ) {

            $object =
                get_queried_object();

            $post_id =
                $object instanceof WP_Post
                    ? (int) $object->ID
                    : (int) get_the_ID();
        }

        if ( ! $post_id ) {
            return '';
        }

        $post_type =
            get_post_type(
                $post_id
            );

        if ( ! $post_type ) {
            return '';
        }


        /**
         * ====================================================
         * TAXONOMIES BEPALEN
         * ====================================================
         *
         * Zonder taxonomy="" worden automatisch alle publieke
         * taxonomies van het huidige post type gebruikt.
         */

        $taxonomies =
            $atts['taxonomy']
                ? array_filter(
                    array_map(
                        'sanitize_key',
                        preg_split(
                            '/\s*,\s*/',
                            $atts['taxonomy']
                        )
                    )
                )
                : get_object_taxonomies(
                    $post_type,
                    'names'
                );

        $taxonomies =
            array_filter(
                $taxonomies,
                function( $taxonomy ) use ( $post_type ) {

                    $object =
                        get_taxonomy(
                            $taxonomy
                        );

                    return (
                        $object &&
                        ! empty( $object->public ) &&
                        in_array(
                            $post_type,
                            (array) $object->object_type,
                            true
                        )
                    );
                }
            );

        if ( ! $taxonomies ) {
            return '';
        }


        /**
         * ====================================================
         * TERMS + BUTTONS
         * ====================================================
         *
         * Alleen terms die daadwerkelijk aan de huidige
         * post gekoppeld zijn worden weergegeven.
         */

        $buttons = [];

        foreach ( $taxonomies as $taxonomy ) {

            $terms =
                wp_get_post_terms(
                    $post_id,
                    $taxonomy
                );

            if (
                is_wp_error( $terms ) ||
                ! $terms
            ) {
                continue;
            }

            foreach ( $terms as $term ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                /**
                 * Native term URL forceren.
                 * Hierdoor maken andere TFSC term_link filters
                 * hier geen vacature-combo URL van.
                 */
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ] = true;

                $url =
                    get_term_link(
                        $term
                    );

                unset(
                    $GLOBALS[
                        'tfsc_force_native_term_link'
                    ]
                );

                if ( is_wp_error( $url ) ) {
                    continue;
                }

                $buttons[] =
                    sprintf(
                        '<a class="tfsc-post-terms__item tfsc-post-terms__item--%1$s" href="%2$s">%3$s</a>',
                        esc_attr(
                            sanitize_html_class(
                                $taxonomy
                            )
                        ),
                        esc_url( $url ),
                        esc_html( $term->name )
                    );
            }
        }

        if ( ! $buttons ) {
            return '';
        }

        return
            '<div class="tfsc-post-terms">'
            . implode( '', $buttons )
            . '</div>';
    }
);

/**
 * TFSC - Pods Admin Connecties + Filters
 *
 * Voor:
 * Pods Admin > Edit Pods
 *
 * Functies:
 * - voegt kolom "Connecties" toe
 * - toont gekoppelde post types bij taxonomies
 * - zoekveld voor Label + Name
 * - filter op Type
 * - filter op Storage Type
 * - filter op Connectie
 * - filters kunnen gecombineerd worden
 * - resetknop
 *
 * Verandert niets aan Pods of de database.
 */

add_action( 'admin_footer', function() {

    /*
     * Alleen:
     * Pods Admin > Edit Pods
     */
    if (
        ! isset( $_GET['page'] ) ||
        'pods' !== sanitize_key( $_GET['page'] )
    ) {
        return;
    }


    /*
     * Niet uitvoeren wanneer een individuele Pod
     * wordt geopend/bewerkt.
     */
    if (
        isset( $_GET['action'] ) &&
        ! in_array(
            sanitize_key( $_GET['action'] ),
            [ '', 'manage' ],
            true
        )
    ) {
        return;
    }


    /*
     * ============================================
     * TAXONOMY → POST TYPE CONNECTIES OPHALEN
     * ============================================
     */

    $taxonomies = get_taxonomies(
        [],
        'objects'
    );

    $connections = [];


    foreach ( $taxonomies as $taxonomy ) {

        if (
            empty( $taxonomy->name ) ||
            empty( $taxonomy->object_type )
        ) {
            continue;
        }


        $labels = [];


        foreach ( $taxonomy->object_type as $post_type_name ) {

            $post_type = get_post_type_object(
                $post_type_name
            );


            if (
                $post_type &&
                ! empty( $post_type->labels->name )
            ) {

                $labels[] =
                    $post_type->labels->name;

            } else {

                $labels[] =
                    $post_type_name;
            }
        }


        $connections[ $taxonomy->name ] =
            array_values(
                array_unique( $labels )
            );
    }

    ?>

    <style>

        /*
         * ============================================
         * FILTERBALK
         * ============================================
         */

        #tfsc-pods-filters {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            align-items: center;

            margin: 12px 0;
            padding: 12px;

            background: #fff;
            border: 1px solid #c3c4c7;

            box-sizing: border-box;
        }


        #tfsc-pods-filters input[type="search"] {
            min-width: 260px;
        }


        #tfsc-pods-filters select {
            min-width: 180px;
        }


        #tfsc-pods-filter-count {
            margin-left: 6px;

            color: #646970;
            font-size: 13px;
        }


        /*
         * Verborgen tabelrijen.
         */
        .tfsc-pods-hidden {
            display: none !important;
        }

    </style>


    <script>

    document.addEventListener(
        'DOMContentLoaded',
        function () {


            /*
             * PHP-connecties beschikbaar maken in JS.
             */
            const tfscConnections =
                <?php echo wp_json_encode( $connections ); ?>;



            /*
             * ============================================
             * PODS-TABEL ZOEKEN
             * ============================================
             */

            function findPodsTable() {

                const tables =
                    document.querySelectorAll(
                        '.wrap table'
                    );


                for (const table of tables) {

                    const headers =
                        Array.from(
                            table.querySelectorAll(
                                'thead th'
                            )
                        ).map(function(th) {

                            return th
                                .textContent
                                .trim()
                                .toLowerCase();

                        });


                    if (
                        headers.includes('label') &&
                        headers.includes('name') &&
                        headers.includes('type') &&
                        headers.includes('storage type')
                    ) {

                        return table;
                    }
                }


                return null;
            }



            const table =
                findPodsTable();


            if (!table) {

                console.log(
                    'TFSC Pods filter: Pods tabel niet gevonden.'
                );

                return;
            }



            /*
             * ============================================
             * CONNECTIES-KOLOM TOEVOEGEN
             * ============================================
             */

            function addConnectionsColumn() {


                const headerRow =
                    table.querySelector(
                        'thead tr'
                    );


                if (!headerRow) {
                    return;
                }


                /*
                 * Niet opnieuw toevoegen.
                 */
                if (
                    headerRow.querySelector(
                        '.tfsc-pods-connections-column'
                    )
                ) {
                    return;
                }


                const headerCells =
                    Array.from(
                        headerRow.querySelectorAll(
                            'th'
                        )
                    );


                const nameIndex =
                    headerCells.findIndex(
                        function(th) {

                            return th
                                .textContent
                                .trim()
                                .toLowerCase()
                                === 'name';
                        }
                    );


                if (nameIndex === -1) {
                    return;
                }



                /*
                 * Header.
                 */
                const newHeader =
                    document.createElement(
                        'th'
                    );


                newHeader.textContent =
                    'Connecties';


                newHeader.className =
                    'tfsc-pods-connections-column';


                headerRow.appendChild(
                    newHeader
                );



                /*
                 * Rijen vullen.
                 */
                const rows =
                    table.querySelectorAll(
                        'tbody tr'
                    );


                rows.forEach(
                    function(row) {


                        const cells =
                            row.querySelectorAll(
                                'td'
                            );


                        if (
                            ! cells.length ||
                            ! cells[nameIndex]
                        ) {
                            return;
                        }


                        const podName =
                            cells[nameIndex]
                                .textContent
                                .trim();


                        const newCell =
                            document.createElement(
                                'td'
                            );


                        newCell.className =
                            'tfsc-pods-connections-column';



                        if (
                            Object.prototype
                                .hasOwnProperty
                                .call(
                                    tfscConnections,
                                    podName
                                )
                            &&
                            tfscConnections[podName]
                                .length
                        ) {


                            newCell.textContent =
                                tfscConnections[podName]
                                    .join(', ');


                        } else {


                            newCell.textContent =
                                '—';
                        }


                        row.appendChild(
                            newCell
                        );
                    }
                );
            }



            /*
             * Eerst connecties toevoegen.
             */
            addConnectionsColumn();



            /*
             * ============================================
             * KOLOMNUMMERS BEPALEN
             * ============================================
             */

            const headers =
                Array.from(
                    table.querySelectorAll(
                        'thead th'
                    )
                );


            function getColumnIndex(name) {

                return headers.findIndex(
                    function(th) {

                        return th
                            .textContent
                            .trim()
                            .toLowerCase()
                            === name.toLowerCase();
                    }
                );
            }



            const columns = {

                label:
                    getColumnIndex(
                        'Label'
                    ),

                name:
                    getColumnIndex(
                        'Name'
                    ),

                type:
                    getColumnIndex(
                        'Type'
                    ),

                storage:
                    getColumnIndex(
                        'Storage Type'
                    ),

                connections:
                    getColumnIndex(
                        'Connecties'
                    )
            };



            /*
             * Veiligheidscontrole.
             */
            if (
                columns.label === -1 ||
                columns.name === -1 ||
                columns.type === -1 ||
                columns.storage === -1 ||
                columns.connections === -1
            ) {

                console.log(
                    'TFSC Pods filter: niet alle kolommen gevonden.',
                    columns
                );

                return;
            }



            const tbody =
                table.querySelector(
                    'tbody'
                );


            if (!tbody) {
                return;
            }


            const rows =
                Array.from(
                    tbody.querySelectorAll(
                        'tr'
                    )
                );


            if (!rows.length) {
                return;
            }



            /*
             * ============================================
             * HULPFUNCTIES
             * ============================================
             */

            function getCellText(
                row,
                index
            ) {


                const cells =
                    row.querySelectorAll(
                        'td'
                    );


                if (!cells[index]) {
                    return '';
                }


                return cells[index]
                    .textContent
                    .trim();
            }



            /*
             * Voor Type en Storage gebruiken we
             * gewoon de volledige celwaarde.
             */
            function getUniqueValues(index) {


                const values =
                    new Set();


                rows.forEach(
                    function(row) {


                        const value =
                            getCellText(
                                row,
                                index
                            );


                        if (
                            value &&
                            value !== '—' &&
                            value !== '-'
                        ) {

                            values.add(
                                value
                            );
                        }
                    }
                );


                return Array
                    .from(values)
                    .sort(
                        function(a, b) {

                            return a.localeCompare(
                                b,
                                undefined,
                                {
                                    numeric: true,
                                    sensitivity: 'base'
                                }
                            );
                        }
                    );
            }



            /*
             * Connecties kunnen meerdere waarden hebben:
             *
             * Beroepen, Vacatures
             *
             * Daarom splitsen we deze apart.
             */
            function getUniqueConnections() {


                const values =
                    new Set();


                rows.forEach(
                    function(row) {


                        const text =
                            getCellText(
                                row,
                                columns.connections
                            );


                        if (
                            !text ||
                            text === '—' ||
                            text === '-'
                        ) {
                            return;
                        }


                        text
                            .split(',')
                            .map(
                                function(value) {

                                    return value.trim();
                                }
                            )
                            .filter(Boolean)
                            .forEach(
                                function(value) {

                                    values.add(
                                        value
                                    );
                                }
                            );
                    }
                );


                return Array
                    .from(values)
                    .sort(
                        function(a, b) {

                            return a.localeCompare(
                                b,
                                undefined,
                                {
                                    numeric: true,
                                    sensitivity: 'base'
                                }
                            );
                        }
                    );
            }



            /*
             * ============================================
             * FILTERBALK MAKEN
             * ============================================
             */

            const filterBar =
                document.createElement(
                    'div'
                );


            filterBar.id =
                'tfsc-pods-filters';



            /*
             * Zoekveld
             */
            const searchInput =
                document.createElement(
                    'input'
                );


            searchInput.type =
                'search';


            searchInput.placeholder =
                'Zoek Label of Name…';



            /*
             * Type
             */
            const typeSelect =
                document.createElement(
                    'select'
                );



            /*
             * Storage
             */
            const storageSelect =
                document.createElement(
                    'select'
                );



            /*
             * Connecties
             */
            const connectionSelect =
                document.createElement(
                    'select'
                );



            /*
             * Reset
             */
            const resetButton =
                document.createElement(
                    'button'
                );


            resetButton.type =
                'button';


            resetButton.className =
                'button';


            resetButton.textContent =
                'Reset';



            /*
             * Teller
             */
            const countLabel =
                document.createElement(
                    'span'
                );


            countLabel.id =
                'tfsc-pods-filter-count';



            /*
             * ============================================
             * DROPDOWNS VULLEN
             * ============================================
             */

            function populateSelect(
                select,
                defaultText,
                values
            ) {


                const option =
                    document.createElement(
                        'option'
                    );


                option.value =
                    '';


                option.textContent =
                    defaultText;


                select.appendChild(
                    option
                );



                values.forEach(
                    function(value) {


                        const option =
                            document.createElement(
                                'option'
                            );


                        option.value =
                            value;


                        option.textContent =
                            value;


                        select.appendChild(
                            option
                        );
                    }
                );
            }



            populateSelect(
                typeSelect,
                'Alle types',
                getUniqueValues(
                    columns.type
                )
            );


            populateSelect(
                storageSelect,
                'Alle storage types',
                getUniqueValues(
                    columns.storage
                )
            );


            populateSelect(
                connectionSelect,
                'Alle connecties',
                getUniqueConnections()
            );



            /*
             * Elementen toevoegen.
             */
            filterBar.appendChild(
                searchInput
            );


            filterBar.appendChild(
                typeSelect
            );


            filterBar.appendChild(
                storageSelect
            );


            filterBar.appendChild(
                connectionSelect
            );


            filterBar.appendChild(
                resetButton
            );


            filterBar.appendChild(
                countLabel
            );



            /*
             * Direct boven de tabel plaatsen.
             */
            table.parentNode.insertBefore(
                filterBar,
                table
            );



            /*
             * ============================================
             * FILTERLOGICA
             * ============================================
             */

            function applyFilters() {


                const search =
                    searchInput
                        .value
                        .trim()
                        .toLowerCase();


                const selectedType =
                    typeSelect.value;


                const selectedStorage =
                    storageSelect.value;


                const selectedConnection =
                    connectionSelect.value;



                let visible =
                    0;



                rows.forEach(
                    function(row) {


                        const label =
                            getCellText(
                                row,
                                columns.label
                            );


                        const name =
                            getCellText(
                                row,
                                columns.name
                            );


                        const type =
                            getCellText(
                                row,
                                columns.type
                            );


                        const storage =
                            getCellText(
                                row,
                                columns.storage
                            );


                        const connectionText =
                            getCellText(
                                row,
                                columns.connections
                            );


                        /*
                         * Label + Name doorzoeken.
                         */
                        const searchable =
                            (
                                label +
                                ' ' +
                                name
                            )
                            .toLowerCase();



                        const matchesSearch =
                            !search ||
                            searchable.includes(
                                search
                            );



                        const matchesType =
                            !selectedType ||
                            type === selectedType;



                        const matchesStorage =
                            !selectedStorage ||
                            storage === selectedStorage;



                        /*
                         * Connecties apart splitsen zodat:
                         *
                         * "Beroepen, Vacatures"
                         *
                         * ook gevonden wordt wanneer alleen
                         * "Vacatures" geselecteerd wordt.
                         */
                        const rowConnections =
                            connectionText
                                .split(',')
                                .map(
                                    function(value) {

                                        return value.trim();
                                    }
                                );


                        const matchesConnection =
                            !selectedConnection ||
                            rowConnections.includes(
                                selectedConnection
                            );



                        /*
                         * AND-logica:
                         *
                         * alles moet overeenkomen.
                         */
                        const matches =
                            matchesSearch &&
                            matchesType &&
                            matchesStorage &&
                            matchesConnection;



                        row.classList.toggle(
                            'tfsc-pods-hidden',
                            !matches
                        );



                        if (matches) {
                            visible++;
                        }
                    }
                );



                countLabel.textContent =
                    visible +
                    ' van ' +
                    rows.length +
                    ' pods';
            }



            /*
             * ============================================
             * EVENTS
             * ============================================
             */

            searchInput.addEventListener(
                'input',
                applyFilters
            );


            typeSelect.addEventListener(
                'change',
                applyFilters
            );


            storageSelect.addEventListener(
                'change',
                applyFilters
            );


            connectionSelect.addEventListener(
                'change',
                applyFilters
            );



            /*
             * Reset.
             */
            resetButton.addEventListener(
                'click',
                function() {


                    searchInput.value =
                        '';


                    typeSelect.value =
                        '';


                    storageSelect.value =
                        '';


                    connectionSelect.value =
                        '';


                    applyFilters();


                    searchInput.focus();
                }
            );



            /*
             * Teller initialiseren.
             */
            applyFilters();

        }
    );

    </script>

    <?php

} );
